// Purge _HASH_LOCK — filtrer entrées > 90 jours (v4 sans $helpers)
const THRESHOLD = 90;
const now = DateTime.now().setZone('America/Toronto');
const rows = $input.first().json.values || [];

if (rows.length <= 1) {
  return [{ json: { purged: 0, kept: 0, toKeep: [rows[0] || []], message: 'Aucune entrée' } }];
}

const header   = rows[0];
const dataRows = rows.slice(1);
const toKeep   = [header];
let purgedCount = 0;

for (const row of dataRows) {
  const tsRaw = row[1] || '';
  if (!tsRaw) { toKeep.push(row); continue; }
  const ts = DateTime.fromISO(tsRaw).setZone('America/Toronto');
  if (!ts.isValid) { toKeep.push(row); continue; }
  const ageDays = now.diff(ts, 'days').days;
  if (ageDays <= THRESHOLD) { toKeep.push(row); } else { purgedCount++; }
}

return [{ json: { purged: purgedCount, kept: toKeep.length - 1, toKeep, message: `${purgedCount} supprimées, ${toKeep.length-1} conservées` } }];

